#include <vector>
#include <algorithm>

class Solution {
public:
    int numSubmat(std::vector<std::vector<int>>& mat) {
        int R = mat.size(), C = mat[0].size();
        std::vector<std::vector<int>> width(R, std::vector<int>(C, 0));
        for (int r = 0; r < R; ++r) {
            for (int c = 0; c < C; ++c) {
                if (mat[r][c] == 1) {
                    width[r][c] = (c > 0 ? width[r][c - 1] : 0) + 1;
                }
            }
        }
        int ans = 0;
        for (int r = 0; r < R; ++r) {
            for (int c = 0; c < C; ++c) {
                int minW = width[r][c];
                for (int k = r; k >= 0; --k) {
                    minW = std::min(minW, width[k][c]);
                    if (minW == 0) break;
                    ans += minW;
                }
            }
        }
        return ans;
    }
};

class Solution {
    public int numSubmat(int[][] mat) {
        int R = mat.length, C = mat[0].length;
        int[][] width = new int[R][C];
        for (int r = 0; r < R; r++) {
            for (int c = 0; c < C; c++) {
                if (mat[r][c] == 1) {
                    width[r][c] = (c > 0 ? width[r][c - 1] : 0) + 1;
                }
            }
        }
        int ans = 0;
        for (int r = 0; r < R; r++) {
            for (int c = 0; c < C; c++) {
                int minW = width[r][c];
                for (int k = r; k >= 0; k--) {
                    minW = Math.min(minW, width[k][c]);
                    if (minW == 0) break;
                    ans += minW;
                }
            }
        }
        return ans;
    }
}

var numSubmat = function(mat) {
    const R = mat.length, C = mat[0].length;
    const width = Array.from({ length: R }, () => new Array(C).fill(0));
    for (let r = 0; r < R; r++) {
        for (let c = 0; c < C; c++) {
            if (mat[r][c] === 1) {
                width[r][c] = (c > 0 ? width[r][c - 1] : 0) + 1;
            }
        }
    }
    let ans = 0;
    for (let r = 0; r < R; r++) {
        for (let c = 0; c < C; c++) {
            let minW = width[r][c];
            for (let k = r; k >= 0; k--) {
                minW = Math.min(minW, width[k][c]);
                if (minW === 0) break;
                ans += minW;
            }
        }
    }
    return ans;
